def shrink_types(types, max_typed_dict_size):
    # Convert to list if needed
    if not isinstance(types, list):
        types = list(types)

    # Handle empty case
    if not types:
        return Any

    # Handle single type case
    if len(types) == 1:
        return DEFAULT_REWRITER.rewrite(types[0])

    # Check if all types are anonymous TypedDicts
    if all(is_anonymous_typed_dict(t) for t in types):
        result = shrink_typed_dict_types(types, max_typed_dict_size)
    else:
        # Remove duplicates while preserving order
        unique_types = []
        seen = set()
        for t in types:
            if not any(types_equal(t, seen_t) for seen_t in unique_types):
                unique_types.append(t)

        if len(unique_types) == 1:
            result = unique_types[0]
        else:
            result = Union[tuple(unique_types)]

    return DEFAULT_REWRITER.rewrite(result)
